import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import HomePage from './pages/HomePage.jsx'

const pages = {
  '/': HomePage,
}

const Page = pages[window.location.pathname] ?? (() => <p>Page not found.</p>)

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <Page />
  </StrictMode>,
)

import { useId, useState } from 'react'
import './ProductPage.css'

const PRODUCT = {
  name: 'Trail Runner 2',
  price: 139.99,
  colors: [
    { name: 'Blue', hex: '#2b5f9e' },
    { name: 'Black', hex: '#222222' },
    { name: 'Grey', hex: '#8a8f98' },
  ],
  sizes: [
    { label: 'US 7', inStock: true },
    { label: 'US 7.5', inStock: true },
    { label: 'US 8', inStock: false },
    { label: 'US 8.5', inStock: true },
    { label: 'US 9', inStock: true },
    { label: 'US 9.5', inStock: true },
    { label: 'US 10', inStock: true },
    { label: 'US 10.5', inStock: false },
    { label: 'US 11', inStock: true },
    { label: 'US 12', inStock: true },
  ],
}

const PHOTOS = [
  { color: '#dfe9f5', accent: '#2b5f9e', alt: 'Trail Runner 2, side view' },
  { color: '#e6e6e6', accent: '#222222', alt: 'Trail Runner 2, top view' },
  { color: '#eceff2', accent: '#8a8f98', alt: 'Trail Runner 2, back view' },
].map((p) => ({
  ...p,
  src:
    'data:image/svg+xml,' +
    encodeURIComponent(
      `<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600">` +
        `<rect width="800" height="600" fill="${p.color}"/>` +
        `<ellipse cx="400" cy="470" rx="260" ry="24" fill="#00000022"/>` +
        `<path d="M180 420 L260 320 Q300 260 360 260 L520 260 Q600 260 620 340 L640 420 Z" fill="${p.accent}"/>` +
        `<path d="M180 420 L640 420 L640 445 Q640 460 620 460 L200 460 Q180 460 180 445 Z" fill="#f5f2ec" stroke="#d9d4c8"/>` +
        `<path d="M300 300 L560 300" stroke="#ffffff88" stroke-width="10"/>` +
        `<path d="M310 330 L570 330" stroke="#ffffff66" stroke-width="10"/>` +
        `<circle cx="330" cy="285" r="7" fill="#f5f2ec"/>` +
        `<circle cx="370" cy="282" r="7" fill="#f5f2ec"/>` +
        `<circle cx="410" cy="280" r="7" fill="#f5f2ec"/>` +
        `</svg>`,
    ),
}))

const TABS = [
  {
    id: 'details',
    label: 'Details',
    content: (
      <>
        <p>
          The Trail Runner 2 is built for long days on rough ground. A grippy
          lugged outsole, breathable mesh upper and a cushioned midsole keep
          you moving comfortably on any trail.
        </p>
        <ul>
          <li>Weight: 285 g (US 9)</li>
          <li>Drop: 8 mm</li>
          <li>Recycled mesh upper</li>
        </ul>
      </>
    ),
  },
  {
    id: 'reviews',
    label: 'Reviews',
    content: (
      <>
        <p>Rated 4.7 out of 5 by 128 runners.</p>
        <blockquote>
          “Light, grippy and true to size. My go-to shoe for rocky trails.” —
          Priya, verified buyer
        </blockquote>
      </>
    ),
  },
  {
    id: 'shipping',
    label: 'Shipping',
    content: (
      <>
        <p>Free standard shipping on orders over $75. Delivery in 3–5 business days.</p>
        <p>Free returns within 30 days, no questions asked.</p>
      </>
    ),
  },
]

const QUESTIONS = [
  {
    q: 'Is the Trail Runner 2 waterproof?',
    a: 'It is water-repellent and dries quickly, but it is not fully waterproof. For wet conditions we recommend pairing it with a waterproof sock.',
  },
  {
    q: 'Does the Trail Runner 2 run true to size?',
    a: 'Yes, most runners find it true to size. If you are between sizes, we suggest going half a size up for long runs.',
  },
  {
    q: 'Can I use it for road running?',
    a: 'You can, but the aggressive lugs are designed for trails. For mostly road use, consider our Road Glide line.',
  },
  {
    q: 'What is the return policy?',
    a: 'You can return unworn shoes within 30 days for a full refund.',
  },
]

function recommendSize(cm, unit) {
  const length = parseFloat(cm)
  if (!Number.isFinite(length) || length <= 0) return null
  if (unit === 'US') {
    const us = Math.round((3 * (length / 2.54) - 22) * 2) / 2
    return `US ${us}`
  }
  const eu = Math.round(length * 1.5 * 2) / 2
  return `EU ${eu}`
}

export default function ProductPage() {
  const [cartCount, setCartCount] = useState(0)
  const [photoIndex, setPhotoIndex] = useState(0)
  const [color, setColor] = useState('Blue')
  const [size, setSize] = useState(null)
  const [sizeOpen, setSizeOpen] = useState(false)
  const [guideOpen, setGuideOpen] = useState(false)
  const [footLength, setFootLength] = useState('')
  const [unit, setUnit] = useState('US')
  const [quantity, setQuantity] = useState(1)
  const [message, setMessage] = useState(null)
  const [saved, setSaved] = useState(false)
  const [activeTab, setActiveTab] = useState('details')
  const [openQuestion, setOpenQuestion] = useState(null)
  const [priceInfoVisible, setPriceInfoVisible] = useState(false)
  const baseId = useId()

  const photo = PHOTOS[photoIndex]
  const recommendation = recommendSize(footLength, unit)

  function changePhoto(delta) {
    setPhotoIndex((i) => (i + delta + PHOTOS.length) % PHOTOS.length)
  }

  function pickSize(option) {
    if (!option.inStock) return
    setSize(option.label)
    setSizeOpen(false)
    setMessage(null)
  }

  function addToCart() {
    if (!size) {
      setMessage({ type: 'error', text: 'Please pick a size before adding to cart.' })
      return
    }
    setCartCount((c) => c + quantity)
    setMessage({
      type: 'success',
      text: `Added to your cart: ${quantity} × ${PRODUCT.name}, ${color}, ${size}.`,
    })
  }

  return (
    <div className="page">
      <a className="skip-link" href="#main-content">
        Skip to main content
      </a>

      <header className="site-header">
        <a className="logo" href="/">
          Stride
        </a>
        <nav className="main-nav" aria-label="Main">
          <a href="/men">Men</a>
          <a href="/women">Women</a>
          <a href="/kids">Kids</a>
        </nav>
        <a className="cart-link" href="/cart">
          Cart ({cartCount})
        </a>
      </header>

      <main id="main-content">
        <nav className="breadcrumb" aria-label="Breadcrumb">
          <ol>
            <li>
              <a href="/shop">Shop</a>
            </li>
            <li>
              <a href="/shop/trail">Trail</a>
            </li>
            <li>
              <span aria-current="page">Trail Runner 2</span>
            </li>
          </ol>
        </nav>

        <div className="product-layout">
          <section className="photos" aria-label="Product photos">
            <img src={photo.src} alt={photo.alt} width="800" height="600" />
            <div className="photo-controls">
              <button type="button" onClick={() => changePhoto(-1)}>
                Previous photo
              </button>
              <span aria-live="polite">
                {photoIndex + 1} / {PHOTOS.length}
              </span>
              <button type="button" onClick={() => changePhoto(1)}>
                Next photo
              </button>
            </div>
          </section>

          <section className="product-info" aria-labelledby="product-title">
            <h1 id="product-title">{PRODUCT.name}</h1>

            <p className="price">
              ${PRODUCT.price.toFixed(2)}{' '}
              <span className="price-info">
                <button
                  type="button"
                  className="info-button"
                  aria-label="Price information"
                  aria-describedby={priceInfoVisible ? `${baseId}-price-tip` : undefined}
                  onMouseEnter={() => setPriceInfoVisible(true)}
                  onMouseLeave={() => setPriceInfoVisible(false)}
                  onFocus={() => setPriceInfoVisible(true)}
                  onBlur={() => setPriceInfoVisible(false)}
                >
                  i
                </button>
                {priceInfoVisible && (
                  <span role="tooltip" id={`${baseId}-price-tip`} className="tooltip">
                    Price includes taxes.
                  </span>
                )}
              </span>
            </p>

            <div className="field">
              <span className="field-label" id={`${baseId}-color-label`}>
                Color: {color}
              </span>
              <div
                className="swatches"
                role="radiogroup"
                aria-labelledby={`${baseId}-color-label`}
              >
                {PRODUCT.colors.map((c) => (
                  <button
                    key={c.name}
                    type="button"
                    role="radio"
                    aria-checked={color === c.name}
                    aria-label={c.name}
                    className="swatch"
                    style={{ backgroundColor: c.hex }}
                    onClick={() => setColor(c.name)}
                  />
                ))}
              </div>
            </div>

            <div className="field size-field">
              <button
                type="button"
                className="size-button"
                aria-expanded={sizeOpen}
                onClick={() => setSizeOpen((o) => !o)}
              >
                Size: {size ?? 'Select size'}
              </button>
              <button
                type="button"
                className="link-button"
                onClick={() => setGuideOpen(true)}
              >
                Size guide
              </button>
              {sizeOpen && (
                <ul className="size-list" role="listbox" aria-label="Sizes">
                  {PRODUCT.sizes.map((s) => (
                    <li
                      key={s.label}
                      role="option"
                      aria-selected={size === s.label}
                      aria-disabled={!s.inStock}
                      className={s.inStock ? '' : 'sold-out'}
                      onClick={() => pickSize(s)}
                    >
                      {s.label}
                      {!s.inStock && ' — sold out'}
                    </li>
                  ))}
                </ul>
              )}
            </div>

            <div className="field quantity-field">
              <button
                type="button"
                aria-label="Decrease quantity"
                onClick={() => setQuantity((q) => Math.max(1, q - 1))}
              >
                −
              </button>
              <input
                type="number"
                aria-label="Quantity"
                min="1"
                max="99"
                value={quantity}
                onChange={(e) => {
                  const value = parseInt(e.target.value, 10)
                  setQuantity(Number.isFinite(value) ? Math.max(1, Math.min(99, value)) : 1)
                }}
              />
              <button
                type="button"
                aria-label="Increase quantity"
                onClick={() => setQuantity((q) => Math.min(99, q + 1))}
              >
                +
              </button>
            </div>

            <div className="actions">
              <button type="button" className="add-to-cart" onClick={addToCart}>
                Add to cart
              </button>
              <button
                type="button"
                className="wishlist"
                aria-label={saved ? 'Remove from wishlist' : 'Save to wishlist'}
                aria-pressed={saved}
                onClick={() => setSaved((s) => !s)}
              >
                {saved ? '♥' : '♡'}
              </button>
            </div>

            {message && (
              <p
                className={`message ${message.type}`}
                role={message.type === 'error' ? 'alert' : 'status'}
              >
                {message.text}
              </p>
            )}
          </section>
        </div>

        <section className="more-info" aria-label="More information">
          <div role="tablist" aria-label="Product information">
            {TABS.map((tab) => (
              <button
                key={tab.id}
                type="button"
                role="tab"
                id={`${baseId}-tab-${tab.id}`}
                aria-selected={activeTab === tab.id}
                aria-controls={`${baseId}-panel`}
                onClick={() => setActiveTab(tab.id)}
              >
                {tab.label}
              </button>
            ))}
          </div>
          <div
            role="tabpanel"
            id={`${baseId}-panel`}
            aria-labelledby={`${baseId}-tab-${activeTab}`}
            tabIndex={0}
          >
            {TABS.find((t) => t.id === activeTab).content}
          </div>
        </section>

        <section className="questions" aria-labelledby={`${baseId}-questions-title`}>
          <h2 id={`${baseId}-questions-title`}>Common questions</h2>
          {QUESTIONS.map((item, index) => {
            const answerId = `${baseId}-answer-${index}`
            const open = openQuestion === index
            return (
              <div key={item.q} className="question">
                <button
                  type="button"
                  aria-expanded={open}
                  aria-controls={answerId}
                  onClick={() => setOpenQuestion(open ? null : index)}
                >
                  {item.q}
                </button>
                <div id={answerId} hidden={!open}>
                  <p>{item.a}</p>
                </div>
              </div>
            )
          })}
        </section>
      </main>

      {guideOpen && (
        <div className="dialog-overlay">
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby={`${baseId}-guide-title`}
            className="dialog"
          >
            <h2 id={`${baseId}-guide-title`}>Size guide</h2>
            <table className="size-chart">
              <caption className="visually-hidden">Foot length to shoe size conversion</caption>
              <thead>
                <tr>
                  <th scope="col">Foot length (cm)</th>
                  <th scope="col">US</th>
                  <th scope="col">EU</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td>25.0</td>
                  <td>7</td>
                  <td>39</td>
                </tr>
                <tr>
                  <td>26.0</td>
                  <td>8</td>
                  <td>40.5</td>
                </tr>
                <tr>
                  <td>27.0</td>
                  <td>9</td>
                  <td>42</td>
                </tr>
                <tr>
                  <td>28.0</td>
                  <td>10</td>
                  <td>44</td>
                </tr>
              </tbody>
            </table>
            <div className="guide-form">
              <label htmlFor={`${baseId}-foot-length`}>Foot length (cm)</label>
              <input
                id={`${baseId}-foot-length`}
                type="number"
                inputMode="decimal"
                min="0"
                step="0.1"
                value={footLength}
                onChange={(e) => setFootLength(e.target.value)}
              />
              <fieldset>
                <legend>Unit</legend>
                <label>
                  <input
                    type="radio"
                    name={`${baseId}-unit`}
                    value="US"
                    checked={unit === 'US'}
                    onChange={() => setUnit('US')}
                  />{' '}
                  US
                </label>
                <label>
                  <input
                    type="radio"
                    name={`${baseId}-unit`}
                    value="EU"
                    checked={unit === 'EU'}
                    onChange={() => setUnit('EU')}
                  />{' '}
                  EU
                </label>
              </fieldset>
              {recommendation && (
                <p className="recommendation" aria-live="polite">
                  Your recommended size: <strong>{recommendation}</strong>
                </p>
              )}
            </div>
            <button type="button" onClick={() => setGuideOpen(false)}>
              Close size guide
            </button>
          </div>
        </div>
      )}

      <footer className="site-footer">
        <div>
          <h2>Customer help</h2>
          <a href="/help">Help center</a>
          <a href="/contact">Contact us</a>
        </div>
        <div>
          <h2>Company</h2>
          <a href="/about">About us</a>
          <a href="/careers">Careers</a>
        </div>
        <div>
          <h2>Follow us</h2>
          <a href="https://instagram.com">Instagram</a>
          <a href="https://facebook.com">Facebook</a>
          <a href="https://youtube.com">YouTube</a>
        </div>
      </footer>
    </div>
  )
}

